const ALIASES = {
  meal: 'food',
  bowl: 'food',
  exercise: 'workout',
  dumbbell: 'workout',
  scale: 'body',
  weight: 'body',
  drink: 'water',
  fire: 'calorie',
  grain: 'carbs',
  avocado: 'fat',
  calendar: 'plan',
  target: 'mission',
  trophy: 'achievement',
  pencil: 'edit',
  arrow_right: 'chevron_right',
  add: 'plus',
  remove: 'minus'
};

function resize(svg, size) {
  const n = String(size).replace(/[^0-9.]/g, '') || '56';
  return svg.replace(/width="64"/, `width="${n}"`).replace(/height="64"/, `height="${n}"`);
}

function label(svg, text) {
  if (!text) return svg;
  return svg.replace(/aria-label="[^"]*"/, `aria-label="${String(text).replace(/"/g, '&quot;')}"`);
}

function getIcon(name, size = 56, ariaLabel = '') {
  const key = ALIASES[name] || name;
  return label(resize(ICONS[key] || ICONS.food, size), ariaLabel);
}

function renderIcon(target, name, size = 56, ariaLabel = '') {
  const el = typeof target === 'string' ? document.querySelector(target) : target;
  if (el) el.innerHTML = getIcon(name, size, ariaLabel);
}

window.IUIcon={ICONS:ICONS,ALIASES:ALIASES,getIcon:getIcon,renderIcon:renderIcon,keys:iconKeys,meta:iconMeta};
window.iuIcon=getIcon;
