window.iuFoodIcon=function(name,size){name=String(name||'');for(var i=0;i<FOOD_KW.length;i++){if(name.indexOf(FOOD_KW[i][0])>-1)return getIcon(FOOD_KW[i][1],size||34);}return getIcon('food',size||34);};
